#include <stdio.h>

static int minimum_coins(const int coins[], int n, int amount, int take[])
{
    int dp[21];
    dp[0] = 0; take[0] = 0;
    for (int a = 1; a <= amount; a++) {
        dp[a] = 21; take[a] = 0;
        for (int i = 0; i < n; i++) {
            int coin = coins[i];
            if (coin <= a && dp[a - coin] + 1 < dp[a]) {
                dp[a] = dp[a - coin] + 1;
                take[a] = coin;
            }
        }
    }
    return dp[amount] == 21 ? -1 : dp[amount];
}

int main(void)
{
    int coins[]={1,3,4},take[21];
    printf("%d\n",minimum_coins(coins,3,6,take));
    return 0;
}

#include <stdio.h>

static int count_ways(const int coins[], int n, int amount)
{
    int ways[21] = {1};
    for (int i = 0; i < n; i++) {
        for (int a = coins[i]; a <= amount; a++) { ways[a] += ways[a - coins[i]]; }
    }
    return ways[amount];
}

int main(void)
{
    int coins[]={1,3,4};
    printf("%d\n",count_ways(coins,3,6));
    return 0;
}

